mapper.select:
SELECT 
FROM dms_shop_service_address
WHERE tenant_id = #{tenantId}
  AND (merchant_id = #{merchantId} OR (merchant_id IS NULL AND shared_to_merchants = 1))
AND address_type = #{addressType}
AND status = #{status}
ORDER BY CASE WHEN merchant_id = #{merchantId} THEN 0 ELSE 1 END, address_type ASC, is_default DESC, id DESC

SELECT 
FROM dms_shop_service_address

    tenant_id = #{tenantId}
    AND address_type = #{addressType}
    AND status = #{status}

ORDER BY address_type ASC, is_default DESC, id DESC

mapper.update:
UPDATE dms_shop_service_address
SET is_default = 0, update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND address_type = #{addressType}

    AND merchant_id = #{merchantId}
    AND merchant_id IS NULL

UPDATE dms_shop_service_address
SET is_default = 0, update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND address_type = #{addressType}
